%[text] # Visualize input signals
%[text] ## Random current case
data = buildInputs_BatteryHV_Random();
%[text] ### Load current
fig = figure; %[output:2980f9db]
fig.Position(3:4) = [1000 300];  % width height %[output:2980f9db]

bevutil1.SignalUtil.plotLookupTable1D( ... %[output:2980f9db]
  data.Input_LoadCurrent_TimePoints.value("s"), ... %[output:2980f9db]
  data.Input_LoadCurrent_Data.value("A"), ... %[output:2980f9db]
  InterpolationInterval=0.5, ParentAxes=axes(fig)) %[output:2980f9db]

ax = fig.CurrentAxes;
xlabel(ax, "Time (s)") %[output:2980f9db]
ylabel(ax, "(A)") %[output:2980f9db]
title(ax, "Load current") %[output:2980f9db]
%[text] ### Heat flow
fig = figure; %[output:1a998725]
fig.Position(3:4) = [400 100];  % width height %[output:1a998725]
bevutil1.SignalUtil.plotLookupTable1D( ... %[output:group:451ce842] %[output:1a998725]
  data.Input_HeatFlow_TimePoints.value("s"), ... %[output:1a998725]
  data.Input_HeatFlow_Data.value("W"), ... %[output:1a998725]
  InterpolationInterval=0.5, ParentAxes=axes(fig)) %[output:group:451ce842] %[output:1a998725]
